package net.hivel.islandsrpg.mob;
import net.hivel.islandsrpg.IslandsRPGPlugin; import net.hivel.islandsrpg.util.LocationUtil; import org.bukkit.Location; import org.bukkit.entity.LivingEntity; import org.bukkit.scheduler.BukkitTask; import java.util.*; import java.util.concurrent.ThreadLocalRandom;
public class MobSpawnService { private final IslandsRPGPlugin plugin; private BukkitTask task; public MobSpawnService(IslandsRPGPlugin p){plugin=p;} public void start(){stop(); task=plugin.getServer().getScheduler().runTaskTimer(plugin,this::tick,100,100);} public void stop(){if(task!=null)task.cancel();} private void tick(){for(CustomMobDefinition d:plugin.mobs().all()){ if(!d.spawningEnabled())continue; long alive=plugin.getServer().getWorlds().stream().flatMap(w->w.getLivingEntities().stream()).filter(e->d.id().equals(plugin.mobs().id(e))).count(); if(alive>=d.maxAlive())continue; int toSpawn=Math.min(d.amount(), d.maxAlive()-(int)alive); for(int i=0;i<toSpawn;i++){ if(d.locations().isEmpty())continue; String raw=d.locations().get(ThreadLocalRandom.current().nextInt(d.locations().size())); Location base=LocationUtil.parse(plugin,raw); if(base==null){plugin.getLogger().warning("Invalid spawn location for "+d.id()+": "+raw); continue;} Location loc=base.clone().add(ThreadLocalRandom.current().nextDouble(-d.radius(),d.radius()),0,ThreadLocalRandom.current().nextDouble(-d.radius(),d.radius())); plugin.mobs().spawn(d.id(),loc); }}} }
